/* Local sound synthesis: no remote audio or hidden player information. */
(()=>{
 let audio,master,previous,muted=localStorage.getItem('poker-muted')==='true',lastHover=0;
 const stackBytes=fetch('/audio/chip-stack-dry-short.wav').then(r=>{if(!r.ok)throw Error('Chip audio unavailable');return r.arrayBuffer();});stackBytes.catch(()=>{});let stackBuffer;
 const winBytes=fetch('/audio/winner-victory.wav').then(r=>{if(!r.ok)throw Error('Winner audio unavailable');return r.arrayBuffer();});winBytes.catch(()=>{});let winBuffer;
 let countdownId=null,countdownKey='',nextTick=0,tickBeat=0;
 let motionHand=null,motionTimes=new Map();const duration=1500,dealGap=180;
 const toggle=document.querySelector('#soundToggle');
 function label(){toggle.innerHTML='<svg class="soundIcon" viewBox="0 0 24 24" aria-hidden="true"><path d="M9 18V5l11-2v13M9 9l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/>'+(muted?'<path d="M3 3l18 18"/>':'')+'</svg>';toggle.title=muted?'Enable sounds':'Mute sounds';toggle.setAttribute('aria-label',toggle.title);toggle.setAttribute('aria-pressed',String(muted));}
 function unlock(){try{if(!audio){const C=window.AudioContext||window.webkitAudioContext;if(!C)return;audio=new C();master=audio.createGain();master.gain.value=muted?0:.22*window.pokerAudio.level('effects');master.connect(audio.destination);stackBytes.then(bytes=>audio.decodeAudioData(bytes.slice(0))).then(buffer=>{stackBuffer=buffer;}).catch(()=>{});winBytes.then(bytes=>audio.decodeAudioData(bytes.slice(0))).then(buffer=>{winBuffer=buffer;}).catch(()=>{});}if(audio.state==='suspended')audio.resume().catch(()=>{});}catch{}}
 window.addEventListener('poker-volume-change',()=>{if(master)master.gain.setTargetAtTime(muted?0:.22*window.pokerAudio.level('effects'),audio.currentTime,.02);});
 function sample(buffer,delay,offset,duration){if(muted||!audio||audio.state!=='running'||!buffer)return;const source=audio.createBufferSource();source.buffer=buffer;source.connect(master);source.start(audio.currentTime+delay,offset,duration);}
 function tone(freq,length=.08,delay=0,type='sine',volume=.3){if(muted||!audio||audio.state!=='running')return;const time=audio.currentTime+delay,osc=audio.createOscillator(),gain=audio.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,time);gain.gain.setValueAtTime(.001,time);gain.gain.exponentialRampToValueAtTime(volume,time+.006);gain.gain.exponentialRampToValueAtTime(.001,time+length);osc.connect(gain);gain.connect(master);osc.start(time);osc.stop(time+length+.01);}
 function noise(length=.09,delay=0){if(muted||!audio||audio.state!=='running')return;const buffer=audio.createBuffer(1,Math.ceil(audio.sampleRate*length),audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const src=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();src.buffer=buffer;filter.type='highpass';filter.frequency.value=1700;gain.gain.value=.13;src.connect(filter);filter.connect(gain);gain.connect(master);src.start(audio.currentTime+delay);}
 function play(name,delay=0){if(name==='hover')tone(1100,.035,delay,'sine',.08);else if(name==='click')tone(650,.045,delay,'triangle',.18);else if(name==='deal'||name==='fold')noise(name==='deal'?.075:.13,delay);else if(name==='check'){tone(330,.05,delay,'triangle');tone(330,.045,delay+.08,'triangle');}else if(name==='call'||name==='raise'){[760,1100,name==='raise'?1450:900].forEach((f,i)=>tone(f,.055,delay+i*.045,'triangle',.17));}else if(name==='join'||name==='bot'){[name==='bot'?520:660,880,1100].forEach((f,i)=>tone(f,.12,delay+i*.07,'sine',.2));}else if(name==='win'){sample(winBuffer,delay,.08,1.7);}else if(name==='allin'){[220,330,440,660,880].forEach((f,i)=>tone(f,.3,delay+i*.07,'triangle',.4));}else if(name==='turn'){tone(784,.18,delay,'sine',.6);tone(1046,.26,delay+.18,'sine',.6);}else if(name==='time'){tone(660,.15,delay);tone(990,.18,delay+.12);}else if(name==='leave')tone(300,.13,delay,'triangle',.2);}
 document.addEventListener('pointerdown',unlock,{capture:true});document.addEventListener('keydown',unlock,{capture:true});
 document.addEventListener('pointerover',e=>{const b=e.target.closest?.('button');if(!b||b.disabled||b.contains(e.relatedTarget)||performance.now()-lastHover<65)return;lastHover=performance.now();play('hover');});
 document.addEventListener('focusin',e=>{if(e.target.matches?.('button:focus-visible')&&!e.target.disabled)play('hover');});
 document.addEventListener('click',e=>{const b=e.target.closest?.('button');if(b&&!b.disabled&&b!==toggle)play('click');});
 toggle.onclick=()=>{unlock();muted=!muted;localStorage.setItem('poker-muted',String(muted));if(master)master.gain.setTargetAtTime(muted?0:.22*window.pokerAudio.level('effects'),audio.currentTime,.02);label();if(!muted)play('click');};label();
 function animateCards(s,id,old){const now=performance.now();if(motionHand!==s.handNumber){motionHand=s.handNumber;motionTimes=new Map();}
 const fresh=!!old&&s.handNumber!==old.handNumber;const boardBefore=(old?.rabbitBoard?.length?old.rabbitBoard.length:old?.board.length)||0;const self=s.players.find(p=>p.id===id);
 const recipients=s.players.filter(p=>p.inHand&&!p.spectating),selfOrder=Math.max(0,recipients.findIndex(p=>p.id===id));
 const group=[...document.querySelectorAll('#myCards .card')].map((el,i)=>({el,key:'hand-'+i,newCard:fresh,delay:(i*recipients.length+selfOrder)*dealGap,duration}));
 document.querySelectorAll('#board .card:not(.empty)').forEach((el,i)=>group.push({el,key:'board-'+i,newCard:!!old&&i>=boardBefore,delay:(i-boardBefore)*180,duration:1100}));
 const oldPlayers=new Map((old?.players||[]).map(p=>[p.id,p]));for(const player of s.players){document.querySelectorAll('.seat[data-id="'+player.id+'"] .publicCards .card').forEach((el,i)=>{if(player.cards[i]==='?')return;const key='shown-'+player.id+'-'+i;const before=oldPlayers.get(player.id);if(!motionTimes.has(key))motionTimes.set(key,old&&before?.cards[i]==='?'?now:now-901);const elapsed=now-motionTimes.get(key);if(elapsed>=900)return;el.classList.add('appearingCard');el.style.animationDelay=(-elapsed)+'ms';});if(player.id===id){document.querySelectorAll('#myCards .card').forEach((el,i)=>{if(!((player.shown||0)&(1<<i)))return;const key='myshown-'+i;const before=oldPlayers.get(id);if(!motionTimes.has(key))motionTimes.set(key,old&&!((before?.shown||0)&(1<<i))?now:now-901);const elapsed=now-motionTimes.get(key);if(elapsed>=900)return;el.classList.add('appearingCard');el.style.animationDelay=(-elapsed)+'ms';});}}
 const table=document.querySelector('#table').getBoundingClientRect();for(const item of group){if(!motionTimes.has(item.key))motionTimes.set(item.key,item.newCard?now+item.delay:now-duration-1);const elapsed=now-motionTimes.get(item.key);if(elapsed>=item.duration||window.matchMedia('(prefers-reduced-motion: reduce)').matches)continue;const box=item.el.getBoundingClientRect(),scale=box.width/(item.el.offsetWidth||box.width);item.el.style.setProperty('--deal-x',((table.x+table.width/2-box.x-box.width/2)/scale)+'px');item.el.style.setProperty('--deal-y',((table.y+table.height/2-box.y-box.height/2)/scale)+'px');item.el.style.setProperty('--deal-duration',item.duration+'ms');item.el.style.animationDelay=(-elapsed)+'ms';item.el.classList.add('dealing');}
 if(fresh&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){let n=0;for(let round=0;round<2;round++)for(const p of recipients){const delay=n++*dealGap;if(p.id===id&&!self?.spectating)continue;const avatar=document.querySelector(`.seat[data-id="${p.id}"] .avatar`);if(!avatar)continue;const box=avatar.getBoundingClientRect(),ghost=document.createElement('span');ghost.className='card back dealGhost';ghost.setAttribute('aria-hidden','true');ghost.style.left=table.x+table.width/2+'px';ghost.style.top=table.y+table.height/2+'px';document.body.append(ghost);const dx=box.x+box.width/2-table.x-table.width/2-20+round*12,dy=box.y-table.y-table.height/2;const a=ghost.animate([{offset:0,opacity:0,transform:'translate(-50%,-50%) scale(.55) rotate(-12deg)'},{offset:.08,opacity:1},{offset:.42,opacity:1,transform:`translate(${dx*.6}px,${dy*.6-35}px) scale(.84) rotate(${round?5:-7}deg)`},{offset:.78,opacity:1,transform:`translate(${dx}px,${dy-5}px) scale(.84) rotate(${round?8:-8}deg)`},{offset:.9,opacity:1,transform:`translate(${dx}px,${dy}px) scale(.8) rotate(${round?8:-8}deg)`},{offset:1,opacity:0,transform:`translate(${dx}px,${dy}px) scale(.8) rotate(${round?8:-8}deg)`}],{duration:1200,delay,fill:'both',easing:'cubic-bezier(.22,.61,.36,1)'});a.onfinish=()=>ghost.remove();setTimeout(()=>ghost.remove(),delay+1400);}}
 }
 setInterval(()=>{const s=previous,p=s?.players[s.turn];const remaining=window.pokerClock.remaining(s?.deadline||0);if(!s||!countdownId||p?.id!==countdownId||p.folded||p.spectating||s.runningOut||s.street==='showdown'||remaining<=0||document.hidden||muted){nextTick=0;return;}const key=[s.code,s.handNumber,s.street,s.turn,s.deadline].join(':');if(key!==countdownKey){countdownKey=key;nextTick=0;tickBeat=0;}const now=performance.now();if(now<nextTick)return;const gap=remaining<=2000?150:remaining<=5000?250:remaining<=10000?500:1000;nextTick=now+gap;tone(tickBeat++%2?1450:1150,.032,0,'triangle',remaining<=5000?.25:.16);},40);
 window.pokerEffects={stack(delay=0){sample(stackBuffer,delay,0,.3);},chatNotification(){tone(880,.14,0,'sine',.45);tone(1175,.22,.12,'sine',.4);},stopCountdown(){countdownId=null;nextTick=0;},tick(){play('hover');},update(s,id){countdownId=id;const old=previous;if(old&&old.code===s.code){const before=new Map(old.players.map(p=>[p.id,p]));for(const p of s.players){const prev=before.get(p.id);if(!prev&&!p.kicked)play(p.bot?'bot':'join');if(prev&&!prev.kicked&&p.kicked)play('leave');if(prev&&p.stats.actions>prev.stats.actions)play(p.action?.startsWith('Raise')?'raise':p.action);if(prev&&prev.chips>0&&p.chips===0&&p.inHand&&!p.folded&&!p.spectating&&s.street!=='showdown')play('allin');if(prev&&p.timeCards<prev.timeCards)play('time');}if(s.handNumber!==old.handNumber){for(let i=0;i<Math.min(s.players.filter(p=>p.inHand).length*2,16);i++)play('deal',i*dealGap/1000);}else if(s.board.length>old.board.length){for(let i=0;i<s.board.length-old.board.length;i++)play('deal',i*.18);}if(s.rabbitBoard?.length&&!old.rabbitBoard?.length){for(let i=0;i<s.rabbitBoard.length-s.board.length;i++)play('deal',i*.18);}if(s.street==='showdown'&&old.street!=='showdown')play('win');if((s.turn!==old.turn||s.street!==old.street||s.handNumber!==old.handNumber)&&s.players[s.turn]?.id===id&&!s.runningOut&&s.street!=='showdown')play('turn');}animateCards(s,id,old?.code===s.code?old:null);previous=s;}};
})();
